package com.nigson.acceptance.pricing;

import com.nigson.commerce.quote.QuoteSkuEligibilityService;import com.nigson.commerce.pricing.PricingAuthority;import com.nigson.shared.problem.*;import com.nigson.shared.security.PrivateWorkload;import java.time.Clock;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import static org.assertj.core.api.Assertions.*;

class QuoteSkuEligibilityPersistenceTest {
 @Test void commerceOwnerChecksMarketSkuQuantityScaleAndOrganizationAuthority(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"quote SKU acceptance requires isolated Commerce PostgreSQL");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);try(var fixture=new PricingFixture(jdbc,manager)){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-206")).findFirst().orElseThrow();var proof=new PrivateWorkload.Proof(route.client(),"synthetic-experience-workload",route,null);var authority=new PricingAuthority(jdbc,Clock.systemUTC(),3,"SYNTHETIC_DISTRIBUTOR_BUY");var service=new QuoteSkuEligibilityService(jdbc,authority);var valid=new QuoteSkuEligibilityService.Input(fixture.customer.party(),fixture.market,null,List.of(new QuoteSkuEligibilityService.Item(fixture.sku,"2")));assertThat(service.validate(proof,valid).items()).containsExactly(new QuoteSkuEligibilityService.Eligible(fixture.sku,0));assertThatThrownBy(()->service.validate(proof,new QuoteSkuEligibilityService.Input(fixture.customer.party(),fixture.market,null,List.of(new QuoteSkuEligibilityService.Item(fixture.sku,"2.1"))))).hasMessage("QUOTE_RULE_VIOLATION");assertThatThrownBy(()->service.validate(proof,new QuoteSkuEligibilityService.Input(UUID.randomUUID(),fixture.market,null,List.of(new QuoteSkuEligibilityService.Item(fixture.sku,"1"))))).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->service.validate(proof,new QuoteSkuEligibilityService.Input(fixture.customer.party(),fixture.market,null,List.of(new QuoteSkuEligibilityService.Item(UUID.randomUUID(),"1"))))).hasMessage("QUOTE_RULE_VIOLATION");var org=fixture.organization();var wholesale=new QuoteSkuEligibilityService.Input(fixture.customer.party(),fixture.market,org,List.of(new QuoteSkuEligibilityService.Item(fixture.sku,"1")));assertThat(service.validate(proof,wholesale).items()).hasSize(1);assertThatThrownBy(()->service.validate(proof,new QuoteSkuEligibilityService.Input(fixture.customer.party(),fixture.market,UUID.randomUUID(),wholesale.items()))).hasMessage("ACCESS_DENIED");}}
}
